\title{The Curvature of a Model Pool:\\ Sharpened Greedy Guarantees for Universal Compression Libraries}
\author{Aristotle}
\date{22 August 2026}

\begin{document}
\maketitle

\begin{abstract}
Let $X$ be a finite message alphabet and let $\{P_i\}$ be a family of candidate statistical models on $X$. The \emph{price of universality} of a finite library $A$ of models is the Shtarkov sum $C(A)=\sum_{x\in X}\max_{i\in A}P_i(x)^{+}$, whose logarithm is the minimax regret of the best universal code for $A$. The functional $C$ is normalized, monotone and submodular, so greedy library design enjoys the classical $1-1/e$ guarantee. We introduce the \emph{curvature of a candidate pool} $\Om$,
\[
  \kappa(\Om)=1-\min_{j\in\Om}\frac{C(\Om)-C(\Om\setminus\{j\})}{C(\{j\})}\in[0,1],
\]
the Conforti--Cornu\'ejols total curvature of the price functional restricted to the pool, and develop its theory. We prove the curvature inequality $C(S\cup\{j\})-C(S)\ge(1-\kappa)C(\{j\})$ for every sub-library $S\subseteq\Om$ and $j\in\Om\setminus S$; curvature superadditivity $C(A\cup B)\ge C(B)+(1-\kappa)(C(A)-C(A\cap B))$, which together with submodularity forces exact modularity of $C$ on a zero-curvature pool; a curvature-sharpened greedy step bounding the optimality gap after $k$ steps by $(n-(1-\kappa)k)$ greedy gains instead of $n$; the resulting product guarantee, whose endpoints are exact optimality of greedy at $\kappa=0$ and the classical $1-1/e$ at $\kappa=1$; the intermediate factor $1-e^{-\kappa}$; the low-curvature gap bound $\kappa(n-1)C(B)$; and monotonicity of curvature in the pool. We then relate curvature to statistical spread. Contrary to the natural conjecture $\kappa\le\delta|\Om|$ for pools of pairwise total-variation diameter $\delta$, we prove the reverse inequality $\kappa\ge1-(|\Om|-1)\delta$: nearly identical pools are \emph{maximally} curved. The conjecture is refuted by two identical fair coins ($\delta=0$, $\kappa=1$). The reverse bound is sharp: for two-source pools $\kappa=1-\TV$ exactly, and every $\kappa_0\in[0,1]$ is realized by an explicit pool of two biased coins. A pigeonhole argument gives $\kappa=1$ whenever $|\Om|>|X|$ or the pool contains a duplicate, so low curvature is available only for pools forming a code in the message alphabet.
\end{abstract}

\noindent\textbf{Keywords:} universal compression, Shtarkov sum, minimax regret, submodularity, total curvature, greedy approximation, model libraries, total variation distance.

\section{Introduction}

\subsection{The price of universality}

A universal code for a family of sources must pay for its ignorance of which source is active. For a finite alphabet $X$ and a finite family $A$ of models, the sharpest formulation of this cost is due to Shtarkov. Define the \emph{envelope} of $A$ and its \emph{Shtarkov sum}:
\[
  \Penv_A(x)=\max_{i\in A}\max\bigl(P_i(x),0\bigr),\qquad \Penv_\emptyset\equiv0,\qquad
  C(A)=\sum_{x\in X}\Penv_A(x).
\]
When each $P_i$ is a probability mass function, the normalized maximum likelihood distribution $\Penv_A/C(A)$ is the unique minimax-regret code for $A$, and its worst-case regret is exactly $\log C(A)$. We call $C(A)$ the \emph{price of universality} of $A$. Note $C(\emptyset)=0$ and $C(\{j\})=1$ for a single probability mass function.

Three structural facts, elementary consequences of the pointwise identity $\max(a,\Penv_A(x))=\Penv_{A\cup\{i\}}(x)$, are used throughout.

\begin{fact}[Normalization and monotonicity]\label{f:mono}
$C(\emptyset)=0$, $C(A)\ge0$, and $A\subseteq B$ implies $C(A)\le C(B)$.
\end{fact}

\begin{fact}[Submodularity / diminishing returns]\label{f:sub}
If $A\subseteq B$ and $j$ is any model, then $C(A\cup\{j\})-C(A)\ge C(B\cup\{j\})-C(B)$.
\end{fact}

\begin{fact}[Covering inequality]\label{f:cover}
For all finite libraries $A,B$:
$C(A\cup B)-C(A)\le\sum_{j\in B}\bigl(C(A\cup\{j\})-C(A)\bigr)$.
\end{fact}

Facts~\ref{f:sub} and~\ref{f:cover} place $C$ in the class of monotone submodular set functions, for which greedy maximization under a cardinality constraint recovers a $1-(1-1/n)^n\ge1-1/e$ fraction of the optimum. This paper is about improving that constant using structure of the pool at hand.

\subsection{The design problem}

Given a large pool $\Om$ of candidate models, select a sub-library $A\subseteq\Om$ with $|A|=k$ maximizing $C(A)$: a library rich enough to explain whatever data arrives. The $1-1/e$ bound is worst-case and attained only by maximally curved instances; if $C$ were modular on $\Om$, greedy would be exactly optimal. The total curvature of Conforti and Cornu\'ejols measures where between these extremes an instance sits. We import it into the universal-compression setting and study both its consequences for greedy design and its relation to the statistics of the pool.

\section{The curvature of a pool}

Throughout, $X$ is a finite alphabet, and libraries and pools are finite sets of model indices.

\subsection{Singletons and subadditive splitting}

\begin{lemma}[Singleton price]\label{l:solo}
$C(\{j\})=\sum_x\max(P_j(x),0)$; in particular $C(\{j\})=1$ when $P_j$ is a probability mass function.
\end{lemma}

\begin{lemma}[Insertion is at most solo value]\label{l:ins}
For every model $j$ and library $A$: $C(A\cup\{j\})-C(A)\le C(\{j\})$.
\end{lemma}
\begin{proof}
Apply Fact~\ref{f:sub} with $\emptyset\subseteq A$ and use $C(\emptyset)=0$.
\end{proof}

\begin{lemma}[Subadditivity across a splitting]\label{l:split}
For all libraries $A,B$:
$C(A)\le C(A\cap B)+\sum_{a\in A\setminus B}C(\{a\})$.
\end{lemma}
\begin{proof}
Apply Fact~\ref{f:cover} to the pair $(A\cap B,\ A\setminus B)$, whose union is $A$, and bound each summand by Lemma~\ref{l:ins}.
\end{proof}

\subsection{Definition}

\begin{definition}[Marginal ratio]
For a pool $\Om$ and index $j$, the \emph{marginal ratio} is
\[
  r_\Om(j)=\frac{C(\Om)-C(\Om\setminus\{j\})}{C(\{j\})},
\]
with the convention $r_\Om(j)=0$ when $C(\{j\})=0$: a worthless model is treated as maximally redundant.
\end{definition}

\begin{definition}[Curvature of a pool]
$\kappa(\Om)=1-\min_{j\in\Om}r_\Om(j)$, the minimum over the empty pool being $1$, so $\kappa(\emptyset)=0$.
\end{definition}

\begin{proposition}[Range]\label{p:range}
$0\le\kappa(\Om)\le1$ for every pool $\Om$.
\end{proposition}
\begin{proof}
Monotonicity gives $C(\Om)\ge C(\Om\setminus\{j\})$ and $C(\{j\})\ge0$, so $r_\Om(j)\ge0$, whence $\kappa\le1$. Lemma~\ref{l:ins} with $A=\Om\setminus\{j\}$ gives $C(\Om)-C(\Om\setminus\{j\})\le C(\{j\})$, so $r_\Om(j)\le1$ for $j\in\Om$; the minimum (default value $1$) is at most $1$, so $\kappa\ge0$.
\end{proof}

\begin{proposition}[Monotonicity in the pool]\label{p:mono}
If $\Om\subseteq\Om'$ then $\kappa(\Om)\le\kappa(\Om')$.
\end{proposition}
\begin{proof}
For $j\in\Om$, submodularity along $\Om\setminus\{j\}\subseteq\Om'\setminus\{j\}$ gives $C(\Om')-C(\Om'\setminus\{j\})\le C(\Om)-C(\Om\setminus\{j\})$, i.e. $r_{\Om'}(j)\le r_\Om(j)$; hence the minimum over the larger pool is no larger.
\end{proof}

Widening the shortlist can only weaken the guarantee: a first hint that redundancy, not diversity, is the enemy.

\subsection{The curvature inequality and superadditivity}

\begin{theorem}[Curvature inequality]\label{t:curvineq}
Let $j\in\Om$ and $S\subseteq\Om$ with $j\notin S$. Then
\[
  C(S\cup\{j\})-C(S)\ \ge\ \bigl(1-\kappa(\Om)\bigr)C(\{j\}).
\]
\end{theorem}
\begin{proof}
Since $S\subseteq\Om\setminus\{j\}$, submodularity gives $C(S\cup\{j\})-C(S)\ge C(\Om)-C(\Om\setminus\{j\})$. If $C(\{j\})=0$ the claim follows from monotonicity. Otherwise $1-\kappa(\Om)\le r_\Om(j)$; multiplying by $C(\{j\})>0$ turns the right-hand side into $C(\Om)-C(\Om\setminus\{j\})$.
\end{proof}

\begin{theorem}[Curvature superadditivity]\label{t:super}
For sub-libraries $A,B\subseteq\Om$,
\[
  C(A\cup B)\ \ge\ C(B)+\bigl(1-\kappa(\Om)\bigr)\bigl(C(A)-C(A\cap B)\bigr).
\]
\end{theorem}
\begin{proof}
By induction on $T$ using Theorem~\ref{t:curvineq} at each insertion, for every $T\subseteq\Om$ disjoint from $B$,
$C(T\cup B)\ge C(B)+(1-\kappa)\sum_{a\in T}C(\{a\})$. Apply this with $T=A\setminus B$, so $T\cup B=A\cup B$, and bound $\sum_{a\in A\setminus B}C(\{a\})\ge C(A)-C(A\cap B)$ by Lemma~\ref{l:split}.
\end{proof}

\begin{corollary}[Zero curvature equals modularity]\label{c:mod}
If $\kappa(\Om)=0$ then $C(A\cup B)+C(A\cap B)=C(A)+C(B)$ for all $A,B\subseteq\Om$.
\end{corollary}
\begin{proof}
Submodularity gives ``$\le$''; Theorem~\ref{t:super} with $\kappa=0$ gives the reverse.
\end{proof}

\section{Curvature-sharpened greedy library design}

\subsection{Greedy runs inside a pool}

\begin{definition}[Pool greedy run]
A sequence $A_0,A_1,\dots$ of libraries is a \emph{greedy run in $\Om$} if $A_0=\emptyset$; for every $k$ there is $j\in\Om$ with $A_{k+1}=A_k\cup\{j\}$; and $C(A_k\cup\{j\})\le C(A_{k+1})$ for every $k$ and every $j\in\Om$. We write $\rho_k=C(A_{k+1})-C(A_k)$ for the $k$-th \emph{greedy gain}.
\end{definition}

Such runs exist: at each step select a maximizer of $j\mapsto C(A_k\cup\{j\})$ over the finite nonempty pool. All guarantees below are therefore non-vacuous.

\begin{lemma}[Structure of a greedy run]\label{l:struct}
For every greedy run in $\Om$:
\begin{enumerate}
\item $A_k\subseteq A_{k+1}\subseteq\Om$ and $\rho_k\ge0$;
\item (antitonicity) $\rho_{k+1}\le\rho_k$;
\item (solo dominance) every $a\in A_k$ satisfies $\rho_k\le C(\{a\})$;
\item (stalling certifies optimality) if $\rho_k\le0$ then $C(B)\le C(A_k)$ for every $B\subseteq\Om$;
\item if $\rho_k>0$ then $|A_{k+1}|=|A_k|+1$.
\end{enumerate}
\end{lemma}
\begin{proof}
(1) is monotonicity. (2) Write $A_{k+2}=A_{k+1}\cup\{j\}$; by submodularity along $A_k\subseteq A_{k+1}$ the gain of $j$ at step $k+1$ is at most its gain at step $k$, which by greedy maximality is at most $\rho_k$. (3) By induction: the element added at step $k$ has gain at most its solo price (Lemma~\ref{l:ins}), and earlier elements inherit the bound through (2). (4) By Fact~\ref{f:cover}, $C(A_k\cup B)-C(A_k)\le\sum_{j\in B}(C(A_k\cup\{j\})-C(A_k))\le|B|\rho_k\le0$; combine with $C(B)\le C(A_k\cup B)$. (5) If the added element were already present the gain would be $0$.
\end{proof}

\subsection{The sharpened step}

\begin{theorem}[Curvature-sharpened greedy step]\label{t:step}
Let $A_\bullet$ be a greedy run in $\Om$, $B\subseteq\Om$ with $|B|=n$, $\kappa=\kappa(\Om)$, and suppose $|A_k|=k$. Then
\[
  C(B)-C(A_k)\ \le\ \bigl(n-(1-\kappa)k\bigr)\rho_k.
\]
\end{theorem}
\begin{proof}
Let $m=|A_k\cap B|$.

\emph{(a) Covering above.} By Fact~\ref{f:cover} applied to $A_k$ and $B\setminus A_k$, and greedy maximality,
\[
  C(A_k\cup B)-C(A_k)\le\sum_{j\in B\setminus A_k}\bigl(C(A_k\cup\{j\})-C(A_k)\bigr)\le(n-m)\rho_k.
\]

\emph{(b) Curvature below.} By the inductive form of Theorem~\ref{t:super} applied to $T=A_k\setminus B$,
\[
  C(A_k\cup B)\ \ge\ C(B)+(1-\kappa)\!\!\sum_{a\in A_k\setminus B}\!\!C(\{a\})\ \ge\ C(B)+(1-\kappa)(k-m)\rho_k,
\]
using solo dominance and $|A_k\setminus B|=k-m$.

\emph{(c) Combine.} Subtracting $C(A_k)$ in (b) and comparing with (a),
\[
  C(B)-C(A_k)\le\bigl(n-(1-\kappa)k\bigr)\rho_k-\kappa m\rho_k\le\bigl(n-(1-\kappa)k\bigr)\rho_k,
\]
since $\kappa,m,\rho_k\ge0$.
\end{proof}

The curvature-free analysis is the case $\kappa=1$, where the bound is $n\rho_k$: each model already chosen shortens the effective horizon by $(1-\kappa)$.

\subsection{The product guarantee}

\begin{definition}[Curvature product]
For $n\in\mathbb{N}$, $\kappa\in[0,1]$, $k\le n$,
\[
  Q_n^\kappa(k)=\prod_{i=0}^{k-1}\left(1-\frac{1}{\,n-(1-\kappa)i\,}\right).
\]
\end{definition}

\begin{lemma}[Properties]\label{l:prod}
For $0\le\kappa\le1$ and $k\le n$: (1) $n-(1-\kappa)i\ge1$ whenever $i+1\le n$, so every factor lies in $[0,1)$ and $Q_n^\kappa(k)\ge0$; (2) $Q_n^\kappa(k)\le(1-1/n)^k$; (3) $Q_n^0(n)=0$.
\end{lemma}
\begin{proof}
(1) $n-(1-\kappa)i\ge n-i\ge1$. (2) Each denominator is at most $n$, so each factor at most $1-1/n$; multiply nonnegative factors. (3) At $\kappa=0$, $i=n-1$ the denominator is $1$ and the factor is $0$.
\end{proof}

\begin{theorem}[Curvature-sharpened greedy guarantee]\label{t:prod}
Let $A_\bullet$ be a greedy run in $\Om$, $B\subseteq\Om$, $n=|B|$, $\kappa=\kappa(\Om)$. Then for every $k\le n$,
\[
  C(B)-C(A_k)\ \le\ Q_n^\kappa(k)\,C(B).
\]
\end{theorem}
\begin{proof}
Induction on $k$ with the invariant: \emph{either} $C(B)\le C(A_k)$ (the claim is then immediate as $Q_n^\kappa(k)C(B)\ge0$) \emph{or} $|A_k|=k$ and the bound holds. For $k=0$: $C(A_0)=0$, $Q_n^\kappa(0)=1$. For the step, if greedy has already won it has won at $k+1$ by monotonicity; otherwise assume $|A_k|=k$ and the bound at $k$, and suppose $C(B)>C(A_{k+1})$. Then $\rho_k>0$ (else Lemma~\ref{l:struct}(4) contradicts), so $|A_{k+1}|=k+1$. With $D=n-(1-\kappa)k\ge1$, Theorem~\ref{t:step} rearranges to $(C(B)-C(A_k))/D\le\rho_k$, hence
\[
  C(B)-C(A_{k+1})=\bigl(C(B)-C(A_k)\bigr)-\rho_k\le\bigl(C(B)-C(A_k)\bigr)\Bigl(1-\frac1D\Bigr),
\]
and $Q_n^\kappa(k+1)=Q_n^\kappa(k)(1-1/D)$ with $1-1/D\ge0$ completes the induction.
\end{proof}

\subsection{Endpoints and interior}

\begin{theorem}[Zero curvature implies exact optimality]\label{t:zero}
If $\kappa(\Om)=0$ and $\emptyset\ne B\subseteq\Om$, then $C(B)\le C(A_{|B|})$.
\end{theorem}
\begin{proof}
Theorem~\ref{t:prod} with $k=n=|B|\ge1$ and Lemma~\ref{l:prod}(3).
\end{proof}

\begin{theorem}[Classical guarantee, for every pool]\label{t:e}
For every pool and every nonempty $B\subseteq\Om$: $(1-e^{-1})C(B)\le C(A_{|B|})$.
\end{theorem}
\begin{proof}
Theorem~\ref{t:prod} with $k=n$, then $Q_n^\kappa(n)\le(1-1/n)^n\le e^{-1}$.
\end{proof}

\begin{theorem}[The factor $1-e^{-\kappa}$]\label{t:ek}
For every pool of curvature $\kappa$ and nonempty $B\subseteq\Om$: $(1-e^{-\kappa})C(B)\le C(A_{|B|})$.
\end{theorem}
\begin{proof}
Immediate from Theorem~\ref{t:e} and $\kappa\le1$, whence $e^{-1}\le e^{-\kappa}$.
\end{proof}

Theorem~\ref{t:ek} is the numerator of the conjectured Conforti--Cornu\'ejols factor $(1-e^{-\kappa})/\kappa$. Since $\kappa\le1$ this numerator is weaker than the classical bound, so the entire content of the conjecture sits in the $1/\kappa$ amplification, which is not obtained here (Section~\ref{s:disc}).

\begin{theorem}[Low-curvature gap bound]\label{t:low}
If $B\subseteq\Om$ and $|B|=n=m+1$, then $C(B)-C(A_n)\le\kappa m\,C(B)=\kappa(n-1)C(B)$.
\end{theorem}
\begin{proof}
Split the product at its last factor: $Q_n^\kappa(n)=Q_n^\kappa(m)\bigl(1-1/(n-(1-\kappa)m)\bigr)$. The prefix satisfies $Q_n^\kappa(m)\le(1-1/n)^m\le1$. The final denominator is $n-(1-\kappa)m=1+\kappa m$, so the last factor equals $\kappa m/(1+\kappa m)\le\kappa m$. Conclude with Theorem~\ref{t:prod}.
\end{proof}

The proof in fact yields the slightly stronger
\[
  C(B)-C(A_n)\ \le\ \Bigl(1-\tfrac1n\Bigr)^{n-1}\frac{\kappa(n-1)}{1+\kappa(n-1)}\,C(B),
\]
the sharpest form obtainable from the recursion. For a target of $n=10$ models drawn from a pool of curvature $\kappa=0.01$, greedy is within $9\%$ of optimal, against the $36.8\%$ slack allowed by the assumption-free theory.

