\section{Curvature versus total variation}

Write $\TV(p,q)=\tfrac12\sum_x|p(x)-q(x)|$, and call a pool $\Om$ of probability mass functions \emph{$\delta$-tight} if $\TV(P_i,P_j)\le\delta$ for all $i,j\in\Om$. The motivating conjecture is that a $\delta$-tight pool is nearly flat, hence $\kappa\le\delta|\Om|$. The truth is exactly reversed.

\subsection{Two identities}

\begin{lemma}[Positive part computes total variation]\label{l:pos}
If $\sum_xp(x)=\sum_xq(x)=1$, then $\sum_x\max(p(x)-q(x),0)=\TV(p,q)$.
\end{lemma}
\begin{proof}
Pointwise $\max(a,0)=(|a|+a)/2$; sum and use $\sum_x(p-q)=0$.
\end{proof}

\begin{lemma}[Price of a pair]\label{l:pair}
For probability mass functions $p,q$: $\sum_x\max(p(x),q(x))=1+\TV(p,q)$.
\end{lemma}
\begin{proof}
Pointwise $\max(a,b)=(a+b+|a-b|)/2$; sum.
\end{proof}

Lemma~\ref{l:pair} already contains the moral: the value added by a second model is exactly the statistical distance between the two. Diversity is value.

\subsection{Nearly identical pools are maximally curved}

\begin{theorem}[Reverse total-variation bound]\label{t:rev}
Let $\Om$ be a $\delta$-tight pool of pointwise nonnegative probability mass functions with $|\Om|\ge2$. Then $\kappa(\Om)\ge1-(|\Om|-1)\delta$.
\end{theorem}
\begin{proof}
Pick $j\in\Om$; its solo price is $1$. Since $\Penv_\Om=\max(P_j,\Penv_{\Om\setminus\{j\}})$ pointwise,
\[
  C(\Om)-C(\Om\setminus\{j\})=\sum_x\max\bigl(P_j(x)-\Penv_{\Om\setminus\{j\}}(x),0\bigr).
\]
For each $x$ the envelope over the nonempty set $\Om\setminus\{j\}$ is attained by some $P_{i(x)}$, so the summand is at most $\max(P_j(x)-P_{i(x)}(x),0)\le\sum_{i\in\Om\setminus\{j\}}\max(P_j(x)-P_i(x),0)$. Summing over $x$, exchanging the order of summation and applying Lemma~\ref{l:pos},
\[
  C(\Om)-C(\Om\setminus\{j\})\le\sum_{i\in\Om\setminus\{j\}}\TV(P_j,P_i)\le(|\Om|-1)\delta,
\]
so $\min_j r_\Om(j)\le(|\Om|-1)\delta$ and $\kappa\ge1-(|\Om|-1)\delta$.
\end{proof}

\subsection{Saturation}

\begin{theorem}[Deletion criterion]\label{t:del}
If $j\in\Om$ and $C(\Om)=C(\Om\setminus\{j\})$, then $\kappa(\Om)=1$.
\end{theorem}
\begin{proof}
$r_\Om(j)=0$ and all ratios are nonnegative, so the minimum is exactly $0$.
\end{proof}

\begin{theorem}[Duplicates force maximal curvature]\label{t:dup}
If $\Om$ contains distinct $i\ne j$ with $P_i=P_j$ pointwise, then $\kappa(\Om)=1$.
\end{theorem}
\begin{proof}
The envelopes of $\Om$ and $\Om\setminus\{j\}$ agree pointwise, since whatever $P_j$ contributes is contributed by the surviving copy $P_i$; apply Theorem~\ref{t:del}.
\end{proof}

\begin{theorem}[Pigeonhole curvature saturation]\label{t:pigeon}
If all models are pointwise nonnegative and $|\Om|>|X|$, then $\kappa(\Om)=1$.
\end{theorem}
\begin{proof}
For each $x$ choose $f(x)\in\Om$ attaining the envelope. The image $f(X)$ has at most $|X|<|\Om|$ elements, so some $j\in\Om$ lies outside it; that $j$ never attains the envelope, so $\Penv_\Om=\Penv_{\Om\setminus\{j\}}$ and Theorem~\ref{t:del} applies.
\end{proof}

Curvature can be below $1$ only if the pool fits inside the alphabet, $|\Om|\le|X|$: curvature-aware library design is meaningful exactly when the pool behaves like a code in the message space.

\subsection{Refutation of the conjecture}

\begin{theorem}[The conjecture $\kappa\le\delta|\Om|$ is false]\label{t:refute}
There is a pool of two probability mass functions on a two-letter alphabet with pairwise total-variation distance $\delta=0$ and curvature $\kappa=1>0=\delta\cdot|\Om|$.
\end{theorem}
\begin{proof}
Take $X=\{0,1\}$ and two indices both carrying the fair coin $(\tfrac12,\tfrac12)$. Their distance is $0$; by Theorem~\ref{t:dup} the curvature is $1$.
\end{proof}

The failure is maximal --- the conjectured bound is $0$, the truth is $1$ --- and by Theorem~\ref{t:rev} it is systematic: statistical similarity forces curvature up, because curvature measures redundancy and similar models are redundant.

\subsection{Sharpness and realizability}

\begin{theorem}[Two-source pools]\label{t:twosource}
Let $a\ne b$ index probability mass functions $P_a,P_b$. Then $\kappa(\{a,b\})=1-\TV(P_a,P_b)$.
\end{theorem}
\begin{proof}
Both solo prices are $1$ and, by Lemma~\ref{l:pair}, $C(\{a,b\})=1+\TV(P_a,P_b)$. Deleting either member leaves price $1$, so both marginal ratios equal $\TV(P_a,P_b)$, and $\kappa=1-\TV(P_a,P_b)$.
\end{proof}

Thus the bound of Theorem~\ref{t:rev}, which reads $\kappa\ge1-\delta$ for $|\Om|=2$, is attained: for pairs, curvature and statistical distance are the same quantity read from opposite ends of $[0,1]$.

\begin{theorem}[The curvature scale is fully realized]\label{t:realize}
For every $\kappa_0\in[0,1]$ there is a pool of two probability mass functions on a two-letter alphabet with pairwise total-variation distance exactly $1-\kappa_0$ and curvature exactly $\kappa_0$.
\end{theorem}
\begin{proof}
Set $d=1-\kappa_0$ and let $Q_i(x)=\tfrac{1+d}{2}$ if $i=x$ and $\tfrac{1-d}{2}$ otherwise, for $i,x\in\{0,1\}$: two coins with bias gap $d$, one favouring each letter. Each is a nonnegative probability mass function and $\TV(Q_0,Q_1)=d$; Theorem~\ref{t:twosource} gives $\kappa=1-d=\kappa_0$.
\end{proof}

Consequently the curvature-indexed family of guarantees of Section~3 is non-degenerate over the whole range of $\kappa$.

\section{Algorithms}

\paragraph{Computing the price.} $C(A)=\sum_x\max_{i\in A}P_i(x)^+$ costs $O(|X||A|)$ operations.

\paragraph{Computing the curvature.} Evaluating $C(\Om)$, then $C(\Om\setminus\{j\})$ and $C(\{j\})$ for each $j$, costs $O(|X||\Om|^2)$. A two-largest-values-per-symbol table reduces this to $O(|X||\Om|)$: record for each $x$ the largest and second-largest model value; then $C(\Om)-C(\Om\setminus\{j\})$ is the sum, over the symbols where $j$ is the unique argmax, of (largest $-$ second largest).

\paragraph{Greedy design.} For $k$ steps, each scanning $|\Om|$ candidates at $O(|X|)$ each given the current envelope: $O(k|\Om||X|)$ in total. The gains $\rho_0\ge\rho_1\ge\cdots$ produced along the way give, via Theorem~\ref{t:step}, a run-time upper bound $(n-(1-\kappa)k)\rho_k$ on the residual gap against \emph{every} target of size $n$; this is typically far tighter than the a priori bound of Theorem~\ref{t:prod}. If $\rho_k=0$, the current library is exactly optimal among all sub-libraries of the pool (Lemma~\ref{l:struct}(4)).

\section{Discussion}\label{s:disc}

\subsection{What curvature does and does not deliver}

Curvature succeeds as an interpolation parameter --- from exact optimality at $\kappa=0$, through the product bound, to $1-1/e$ at $\kappa=1$, with a linear-in-$\kappa$ low-curvature guarantee --- and as a diagnostic: computable in time linear in the pool size, detecting duplicates and pigeonhole-redundant pools, and monotone in the pool so that pruning a shortlist can only improve the guarantee.

It does not deliver the full factor $(1-e^{-\kappa})/\kappa$. The obstruction is structural: the recursion of Theorem~\ref{t:prod} propagates a single scalar --- the current gap --- and discards all information about earlier gains, whereas the conjectured factor is the optimal value of a linear program in the entire gain vector.

\subsection{The reversal of the total-variation intuition}

The intuition behind $\kappa\le\delta|\Om|$ --- ``nearly identical models leave little to choose between, so any choice is nearly optimal'' --- conflates two notions of near-optimality. A $\delta$-tight pool does have a small \emph{absolute} range of prices: for nonempty $A\subseteq\Om$ and $j\in A$, pointwise $\Penv_A(x)\le P_j(x)+\sum_{i\in A\setminus\{j\}}\max(P_i(x)-P_j(x),0)$, so $1\le C(A)\le1+(|\Om|-1)\delta$ by Lemma~\ref{l:pos}. But curvature is a \emph{relative} quantity, a ratio of marginal to solo value; precisely because the absolute range is small, marginal values are small relative to the solo value $1$, driving the ratio to $0$ and the curvature to $1$.

Both statements hold at once: a $\delta$-tight pool is maximally curved \emph{and} every selection from it is within an additive $(|\Om|-1)\delta$ of optimal. In the near-identical regime the right guarantee is additive, not multiplicative. For the multiplicative guarantees of Section~3 to be strong one needs a well-separated pool, and Theorem~\ref{t:twosource} quantifies exactly how well-separated in the two-source case.

\subsection{Practical reading}

For a practitioner assembling a candidate pool for later greedy selection: deduplicate, since one duplicated pair sets $\kappa=1$ (Theorem~\ref{t:dup}); keep the pool no larger than the alphabet, or curvature saturates combinatorially (Theorem~\ref{t:pigeon}); prefer a small, diverse shortlist to a large, redundant one, since curvature is monotone in the pool (Proposition~\ref{p:mono}) and driven up by statistical similarity (Theorem~\ref{t:rev}); and report the last greedy gain $\rho_k$, which certifies the residual gap at run time far more tightly than any a priori bound.

\section{Future directions}

\paragraph{What survived.} The curvature inequality, curvature superadditivity, the sharpened step $\mathrm{gap}_k\le(n-(1-\kappa)k)\rho_k$, the product guarantee, exact optimality at $\kappa=0$, $1-1/e$ at every curvature, monotonicity of curvature in the pool, the low-curvature gap bound $\kappa(n-1)$, and the factor $1-e^{-\kappa}$.

\paragraph{What needed a different definition of ``nearly identical''.} The conjecture $\kappa\le\delta|\Om|$ is false: two identical fair coins have $\delta=0$ and $\kappa=1$. The correct statement runs the other way, $\kappa\ge1-(|\Om|-1)\delta$.

\paragraph{What was sharpened.} For two-source pools the curvature is exactly $1-\delta$, so the lower bound is attained, and every $\kappa_0\in[0,1]$ is realized by an explicit pool of two biased coins.

\paragraph{What is true but not reached.} The exact factor $(1-e^{-\kappa})/\kappa$ is consistent with extensive random experiments but is not implied by the step-by-step recursion used here; for $\kappa=0.1$, $n=3$ the proved factor is $0.9418$ against the conjectured $0.9516$.

\paragraph{Direction 1: an LP-certified Conforti--Cornu\'ejols factor.} The $(1-e^{-\kappa})/\kappa$ factor is not a consequence of any single-step recursion: it is the value of a linear program whose variables are the whole vector of greedy gains $(\rho_0,\dots,\rho_{n-1})$, constrained by monotonicity of the gains, the covering inequalities at every step, and the curvature inequality applied to every already-chosen model. All the inequality generators are in hand, so the missing ingredient is a finite-dimensional duality certificate, which can be guessed numerically and verified symbolically.

\paragraph{Direction 2: a curvature--capacity trade-off.} Pigeonhole saturation turns curvature into a capacity statement: a pool can have $\kappa<1$ only if $|\Om|\le|X|$, so the useful regime is exactly the one in which the pool is a code in the alphabet, and the achievable curvature should be governed by how separated the models are in the simplex. Both sides are available --- the saturation and the bound $\kappa\ge1-(|\Om|-1)\delta$ --- and the case $|\Om|=2$ is settled exactly by $\kappa=1-\TV$. The general question is a packing problem: over all pools of $m$ probability mass functions on an alphabet of size $N$, what is $\min\kappa$, and which configurations attain it?

\paragraph{Further questions.} Matroid-constrained greedy has a $1/(1+\kappa)$-type guarantee in the general submodular setting; specializing it to the Shtarkov functional with structured constraints would give deployable design rules. For continuous alphabets the pigeonhole obstruction dissolves and curvature should be controlled by a covering number of the model class. Other divergences (Hellinger, R\'enyi) might give sharper two-sided control of $\kappa$ for exponential families. Finally, for a smooth parametric family, is the curvature of a finite pool of parameter values asymptotically governed by the Fisher information geometry, in analogy with the classical $\tfrac d2\log n$ asymptotics of the Shtarkov sum?

